const { app, BrowserWindow, ipcMain } = require('electron');
const path = require('path');
const fs = require('fs');
const initSqlJs = require('sql.js');

let mainWindow;
let db = null;       // instância sql.js
let dbPath = '';     // caminho do arquivo .db no disco

// Persiste o banco no disco após cada operação de escrita
function salvar() {
  if (db && dbPath) {
    const data = db.export();
    fs.writeFileSync(dbPath, Buffer.from(data));
  }
}

// Helper: executa SELECT e retorna array de objetos
function all(sql, params = []) {
  const stmt = db.prepare(sql);
  stmt.bind(params);
  const rows = [];
  while (stmt.step()) rows.push(stmt.getAsObject());
  stmt.free();
  return rows;
}

// Helper: executa SELECT e retorna 1 objeto (ou undefined)
function get(sql, params = []) {
  const rows = all(sql, params);
  return rows[0];
}

// Helper: executa INSERT/UPDATE/DELETE e retorna { lastInsertRowid, changes }
function run(sql, params = []) {
  db.run(sql, params);
  const idRes = db.exec('SELECT last_insert_rowid() AS id');
  const lastInsertRowid = idRes.length ? idRes[0].values[0][0] : 0;
  const chRes = db.exec('SELECT changes() AS c');
  const changes = chRes.length ? chRes[0].values[0][0] : 0;
  salvar();
  return { lastInsertRowid, changes };
}

// ===================== BANCO DE DADOS (SQLite local via sql.js) =====================
async function createDatabase() {
  const SQL = await initSqlJs();
  const userData = app.getPath('userData');
  if (!fs.existsSync(userData)) fs.mkdirSync(userData, { recursive: true });
  dbPath = path.join(userData, 'pdv.db');

  if (fs.existsSync(dbPath)) {
    const buf = fs.readFileSync(dbPath);
    db = new SQL.Database(buf);
  } else {
    db = new SQL.Database();
  }

  db.run(`
    CREATE TABLE IF NOT EXISTS produtos (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      codigo TEXT,
      nome TEXT NOT NULL,
      preco REAL NOT NULL,
      custo REAL DEFAULT 0,
      estoque INTEGER DEFAULT 0,
      categoria TEXT,
      fornecedor TEXT,
      unidade TEXT DEFAULT 'UN',
      data_cadastro DATETIME DEFAULT CURRENT_TIMESTAMP
    );
    CREATE TABLE IF NOT EXISTS vendas (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      numero TEXT UNIQUE,
      data_hora DATETIME DEFAULT CURRENT_TIMESTAMP,
      subtotal REAL NOT NULL,
      desconto REAL DEFAULT 0,
      total REAL NOT NULL,
      cliente_id INTEGER,
      vendedor_id INTEGER,
      observacoes TEXT,
      forma_pagamento TEXT DEFAULT 'Dinheiro',
      status TEXT DEFAULT 'concluida'
    );
    CREATE TABLE IF NOT EXISTS itens_venda (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      venda_id INTEGER REFERENCES vendas(id),
      produto_id INTEGER REFERENCES produtos(id),
      quantidade INTEGER NOT NULL,
      preco_unitario REAL NOT NULL,
      desconto REAL DEFAULT 0,
      subtotal REAL NOT NULL
    );
    CREATE TABLE IF NOT EXISTS clientes (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      nome TEXT NOT NULL,
      cpf_cnpj TEXT,
      rg_ie TEXT,
      telefone TEXT,
      email TEXT,
      endereco TEXT,
      numero TEXT,
      complemento TEXT,
      bairro TEXT,
      cidade TEXT,
      estado TEXT,
      cep TEXT,
      data_nascimento TEXT,
      observacoes TEXT,
      debito REAL DEFAULT 0,
      credito REAL DEFAULT 0,
      data_cadastro DATETIME DEFAULT CURRENT_TIMESTAMP
    );
    CREATE TABLE IF NOT EXISTS vendedores (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      nome TEXT NOT NULL,
      comissao REAL DEFAULT 5,
      ativo INTEGER DEFAULT 1
    );
    CREATE TABLE IF NOT EXISTS fornecedores (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      nome TEXT NOT NULL,
      tipo TEXT DEFAULT 'Fornecedor',
      cpf_cnpj TEXT,
      rg_ie TEXT,
      telefone TEXT,
      email TEXT,
      endereco TEXT,
      numero TEXT,
      complemento TEXT,
      bairro TEXT,
      cidade TEXT,
      estado TEXT,
      cep TEXT
    );
    CREATE TABLE IF NOT EXISTS caixas (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      numero TEXT UNIQUE,
      data_abertura DATETIME DEFAULT CURRENT_TIMESTAMP,
      data_fechamento DATETIME,
      saldo_inicial REAL DEFAULT 0,
      saldo_final REAL,
      total_vendas REAL DEFAULT 0,
      lucro_bruto REAL DEFAULT 0,
      usuario_abertura TEXT,
      usuario_fechamento TEXT,
      status TEXT DEFAULT 'aberto'
    );
    CREATE TABLE IF NOT EXISTS movimentacoes_caixa (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      caixa_id INTEGER REFERENCES caixas(id),
      tipo TEXT NOT NULL,
      valor REAL NOT NULL,
      descricao TEXT,
      data_hora DATETIME DEFAULT CURRENT_TIMESTAMP
    );
    CREATE TABLE IF NOT EXISTS contas_pagar (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      descricao TEXT NOT NULL,
      fornecedor TEXT,
      valor REAL NOT NULL,
      valor_pago REAL,
      vencimento DATE,
      pago_em DATE,
      status TEXT DEFAULT 'pendente',
      categoria TEXT,
      referencia TEXT
    );
    CREATE TABLE IF NOT EXISTS transacoes_estoque (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      tipo TEXT NOT NULL,
      produto_id INTEGER REFERENCES produtos(id),
      quantidade INTEGER NOT NULL,
      motivo TEXT,
      data_hora DATETIME DEFAULT CURRENT_TIMESTAMP,
      funcionario TEXT
    );
    CREATE TABLE IF NOT EXISTS categorias (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      nome TEXT UNIQUE NOT NULL
    );
  `);
  salvar();
  seedData();
}

